effect.shader:
const int TAPS = 24;
void main(){
  vec2 uv = acScreenNorm;
  vec4 src = texture2DCv(inputImg.texture, uv);
  float a = max(src.a, 1e-4);
  vec3 c = src.rgb / a;
  vec3 acc = vec3(0.0);
  float w = 1.0;
  for (int i = 0; i < TAPS; i++){
    float t = (float(i) / float(TAPS - 1) - 0.5) * length;
    vec4 s = texture2DCv(inputImg.texture, uv + vec2(t, 0.0));
    vec3 sc = s.rgb / max(s.a, 1e-4);
    acc += sc * smoothstep(threshold, 1.0, gmLum(sc)) * w;
    w *= 0.94;
  }
  acc /= float(TAPS);
  vec3 col = c + acc * streakColor.rgb * intensity * mixAmt;
  gl_FragColor = vec4(clamp(col, 0.0, 1.0) * a, a);
}
